 * Finds the closest matching property name from a list of candidates
 * using Levenshtein distance.
 *
 * Only returns suggestions when the distance is <= 3.
 * If multiple candidates tie for the best match,
 * returns the one that comes first alphabetically.
 *
 * @param {string} missingProperty - The property name that was not found.
 * @param {string[]} candidates - List of candidate property names.
 * @returns {string|null} The closest matching property or null.
 */
function findClosestMatch(missingProperty, candidates) {
  let bestDistance = Infinity;
  let bestMatch = null;

  for (const candidate of candidates) {
    const dist = levenshteinDistance(missingProperty, candidate);

    if (dist <= 3) {
      if (dist < bestDistance) {
        bestDistance = dist;
        bestMatch = candidate;
      } else if (dist === bestDistance) {
        // Tie-breaker: alphabetically first
        if (candidate < bestMatch) {
          bestMatch = candidate;
        }
      }
    }
  }

  return bestMatch;
}

