const { createDebugHelper, levenshteinDistance } = require('./ko-debug');

// Define a sample ViewModel with the required properties
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

// Create the debug helper
const debug = createDebugHelper(sampleViewModel);

// Track results
let allPassed = true;
let testCount = 0;
let passCount = 0;

function runTest(description, actual, expected) {
  testCount++;
  const passed = actual === expected;
  if (passed) {
    passCount++;
    console.log(`PASS: ${description}`);
  } else {
    allPassed = false;
    console.log(`FAIL: ${description}`);
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    console.log(`  Actual:   ${JSON.stringify(actual)}`);
  }
}

// ============================================================
// Test 1: Missing property "item" should suggest "items"
// ============================================================
const test1Result = debug.diagnoseMissingProperty('item');
runTest(
  'Test 1: Missing property "item" should suggest "items"',
  test1Result.suggestion,
  'items'
);
// Verify structure
runTest(
  'Test 1: Result has correct structure',
  test1Result,
  {
    error: true,
    missingProperty: 'item',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'].sort(),
    suggestion: 'items'
  }
);

// ============================================================
// Test 2: Missing property "selctedItem" (typo) should suggest "selectedItem"
// ============================================================
const test2Result = debug.diagnoseMissingProperty('selctedItem');
runTest(
  'Test 2: Missing property "selctedItem" (typo) should suggest "selectedItem"',
  test2Result.suggestion,
  'selectedItem'
);

// ============================================================
// Test 3: Missing property "completelyWrong" should have null suggestion
// ============================================================
const test3Result = debug.diagnoseMissingProperty('completelyWrong');
runTest(
  'Test 3: Missing property "completelyWrong" should have null suggestion',
  test3Result.suggestion,
  null
);

// ============================================================
// Test 4: Missing property "isLoad" should suggest "isLoading"
// ============================================================
const test4Result = debug.diagnoseMissingProperty('isLoad');
runTest(
  'Test 4: Missing property "isLoad" should suggest "isLoading"',
  test4Result.suggestion,
  'isLoading'
);

// ============================================================
// Additional verification tests
// ============================================================

// Verify Levenshtein distance function directly
runTest(
  'Extra: Levenshtein distance("item", "items") should be 1',
  levenshteinDistance('item', 'items'),
  1
);
runTest(
  'Extra: Levenshtein distance("selctedItem", "selectedItem") should be 1',
  levenshteinDistance('selctedItem', 'selectedItem'),
  1
);
runTest(
  'Extra: Levenshtein distance("completelyWrong", "items") should be > 3',
  levenshteinDistance('completelyWrong', 'items') > 3,
  true
);
runTest(
  'Extra: Levenshtein distance("isLoad", "isLoading") should be <= 3',
  levenshteinDistance('isLoad', 'isLoading') <= 3,
  true
);

// Verify availableProperties is sorted alphabetically
const test5Result = debug.diagnoseMissingProperty('nonexistent');
runTest(
  'Extra: availableProperties is sorted alphabetically',
  JSON.stringify(test5Result.availableProperties),
  JSON.stringify(['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'])
);

// ============================================================
// Summary
// ============================================================
console.log(`\n-------------------`);
console.log(`Tests: ${passCount}/${testCount} passed`);
console.log(`-------------------`);

if (allPassed) {
  console.log('All tests passed!');
  process.exit(0);
} else {
  console.log('Some tests failed!');
  process.exit(1);
}
